<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useAuthStore } from '@/stores/auth'
import { loadJobs, loadJob, uploadKnowledge, transition, searchKnowledge, downloadSource, type KnowledgeJob, type Source } from './api'
const auth = useAuthStore()
const can = (p: string) => auth.hasExtensionPermission(`knowledge:${p}`)
const jobs = ref<KnowledgeJob[]>([]), selected = ref<KnowledgeJob | null>(null), sources = ref<Source[]>([])
const file = ref<File | null>(null), id = ref(''), version = ref(''), audiences = ref(''), effective = ref(''), withdraw = ref(''), searchAudience = ref(''), query = ref(''), resultAudience = ref('')
const busy = ref(false), error = ref(''), notice = ref(''), reviewed = ref(false)
async function run(fn: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ''; notice.value = ''; try { await fn() } catch (e: unknown) { const code = (e as { response?: { status?: number } }).response?.status; error.value = code === 409 ? 'This record changed. Refresh and review its current version before acting.' : code === 403 || code === 404 ? 'Your current permissions and audience grants do not permit this action.' : 'The request could not be completed. Refresh to check its outcome before retrying.' } finally { busy.value = false } }
async function refresh() { jobs.value = await loadJobs(); if (selected.value) { selected.value = await loadJob(selected.value.id); reviewed.value = false } }
async function open(job: KnowledgeJob) { await run(async () => { selected.value = await loadJob(job.id); reviewed.value = false }) }
async function upload() { await run(async () => { if (!file.value) return; if (file.value.size > 20 * 1024 * 1024) { error.value = 'Maximum upload size is 20 MiB.'; return }; const created = await uploadKnowledge(file.value, { document_id: id.value.trim(), version: version.value.trim(), filename: file.value.name, media_type: file.value.type || 'application/octet-stream', audiences: audiences.value.split(',').map(a => a.trim()).filter(Boolean), effective_at: new Date(effective.value).toISOString(), ...(withdraw.value ? { withdraw_at: new Date(withdraw.value).toISOString() } : {}) }); await refresh(); selected.value = await loadJob(created.id); notice.value = 'Upload quarantined. Refresh for trusted scanner and extraction results.' }) }
async function act(action: 'approve' | 'publish' | 'retire') { await run(async () => { if (!selected.value) return; selected.value = await transition(selected.value, action); reviewed.value = false; jobs.value = await loadJobs(); notice.value = `Saved: ${selected.value.status}.` }) }
async function search() { await run(async () => { sources.value = []; const audience = searchAudience.value.trim(); sources.value = await searchKnowledge(audience, query.value); resultAudience.value = audience }) }
function choose(e: Event) { file.value = (e.target as HTMLInputElement).files?.[0] ?? null }
onMounted(() => run(refresh))
</script>
<template>
 <main class="knowledge-page">
  <header><div><h1>Governed knowledge</h1><p>Upload original documents, review extracted pages and publish approved versions to exact audiences.</p></div><button :disabled="busy" @click="run(refresh)">Refresh status</button></header>
  <p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><p v-if="busy" role="status">Loading or saving…</p>
  <section v-if="can('upload')"><h2>Upload to quarantine</h2><form @submit.prevent="upload">
   <label>Original file (maximum 20 MiB)<input type="file" required :disabled="busy" @change="choose" /></label>
   <label>Document identifier<input v-model="id" required maxlength="200" :disabled="busy" /></label><label>Version<input v-model="version" required maxlength="100" :disabled="busy" /></label>
   <label>Audience identifiers (comma separated)<input v-model="audiences" required :disabled="busy" /></label><label>Effective from<input v-model="effective" type="datetime-local" required :disabled="busy" /></label><label>Withdraw at (optional)<input v-model="withdraw" type="datetime-local" :disabled="busy" /></label><button :disabled="busy || !file">Upload original</button>
  </form></section>
  <section><h2>Processing and publication</h2><p>Failed and unknown jobs stay quarantined. Only a trusted worker can complete scanning and extraction.</p><p v-if="!jobs.length">No uploads are available within your current scopes.</p><div class="table-scroll"><table v-if="jobs.length"><thead><tr><th>Document</th><th>Version</th><th>Status</th><th>Audiences</th><th>Review</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td>{{ job.metadata.document_id }}</td><td>{{ job.metadata.version }}</td><td>{{ job.status }}</td><td>{{ job.metadata.audiences.join(', ') }}</td><td><button :disabled="busy" @click="open(job)">Open</button></td></tr></tbody></table></div></section>
  <section v-if="selected"><h2>{{ selected.metadata.document_id }} · {{ selected.metadata.version }}</h2><p>Status: {{ selected.status }} · Revision {{ selected.version }}</p><p>Effective {{ new Date(selected.metadata.effective_at).toLocaleString() }} · Audiences {{ selected.metadata.audiences.join(', ') }}</p><p v-if="selected.metadata.withdraw_at && selected.metadata.withdraw_at !== '0001-01-01T00:00:00Z'">Withdraws {{ new Date(selected.metadata.withdraw_at).toLocaleString() }}</p><p v-if="selected.failure">Processing outcome: {{ selected.failure }}</p><p class="hash" v-if="selected.manifest_hash">Approved manifest binding: {{ selected.manifest_hash }}</p>
   <article v-for="page in selected.pages" :key="page.Number"><h3>Original page {{ page.Number }}</h3><p>{{ page.Method }} · {{ page.ExtractorRevision }}</p><pre>{{ page.Text || '(Blank page)' }}</pre></article>
   <template v-if="selected.status === 'processed' && can('review')"><label><input v-model="reviewed" type="checkbox" :disabled="busy" />I reviewed every extracted page, audiences, version and effective dates.</label><button :disabled="busy || !reviewed" @click="act('approve')">Approve this exact manifest</button></template>
   <template v-if="selected.status === 'approved' && can('publish')"><p>Publication requires a different authorized person from the reviewer.</p><button :disabled="busy" @click="act('publish')">Publish approved version</button></template><button v-if="selected.status === 'published' && can('retire')" :disabled="busy" @click="act('retire')">Withdraw publication</button>
  </section>
  <section v-if="can('read')"><h2>Find approved sources and forms</h2><form @submit.prevent="search"><label>Audience<input v-model="searchAudience" required :disabled="busy" /></label><label>Search words<input v-model="query" type="search" required maxlength="4096" :disabled="busy" /></label><button :disabled="busy">Search current publications</button></form><p v-if="!sources.length">No current results loaded.</p><article v-for="source in sources" :key="source.Reference"><h3>{{ source.DocumentID }} · {{ source.Version }} · Page {{ source.Page.Number }}</h3><pre>{{ source.Page.Text }}</pre><p class="hash">Citation {{ source.Reference }} · Content SHA-256 {{ source.ContentHash }}</p><button :disabled="busy" @click="run(() => downloadSource(source, resultAudience))">Download original document or form</button></article></section>
 </main>
</template>
<style scoped>
.knowledge-page{max-width:1100px;margin:auto;padding:2rem}header{display:flex;justify-content:space-between;gap:1rem}h1{font-size:1.7rem;font-weight:650}h2{font-size:1.25rem;font-weight:600}h3{font-weight:600}p{margin:.6rem 0;color:hsl(var(--muted-foreground))}section{margin-top:1.5rem;padding:1.25rem;border:1px solid hsl(var(--border));border-radius:.5rem}label{display:block;margin:.8rem 0}input,button{padding:.5rem;border:1px solid hsl(var(--border));border-radius:.25rem;background:hsl(var(--background))}input{margin-left:.6rem}button:disabled{opacity:.45}article{border-top:1px solid hsl(var(--border));padding:1rem 0;margin-top:1rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit;max-height:30rem;overflow:auto}.hash{font-family:monospace;overflow-wrap:anywhere;font-size:.8rem}.error{color:#b91c1c}.table-scroll{overflow:auto}table{width:100%;text-align:left}th,td{padding:.6rem;border-bottom:1px solid hsl(var(--border))}@media(max-width:650px){.knowledge-page{padding:1rem}header{display:block}input{display:block;margin:.4rem 0;max-width:100%}}
</style>
